import { main as getOpexData } from "./opex_core.ts";

type Query = Record<string, string | string[] | undefined>;
type Action = "collectives" | "snapshots" | "dashboard" | "refresh" | "status" | "transactions";

const RAW_APP_API_PARAM = "__wmill_public_api";
const RAW_APP_CSS_BASE64 = "";
const RAW_APP_JS_BASE64 = "";

function decodeBase64(value: string) {
  const binary = atob(value);
  const bytes = Uint8Array.from(binary, (char) => char.charCodeAt(0));
  return new TextDecoder().decode(bytes);
}

function renderRawAppHtml() {
  const css = decodeBase64(RAW_APP_CSS_BASE64);
  const js = decodeBase64(RAW_APP_JS_BASE64);
  return `<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <meta name="robots" content="noindex, nofollow" />
    <title>Beforest OPEX Dashboard</title>
    <style>${css}</style>
  </head>
  <body>
    <div id="root"></div>
    <script>
      window.wmill = {
        backend: {
          get_opex_data: async function(args) {
            var url = new URL(window.location.href);
            url.search = "";
            url.searchParams.set(${JSON.stringify(RAW_APP_API_PARAM)}, "get_opex_data");
            Object.entries(args || {}).forEach(function(entry) {
              var key = entry[0];
              var value = entry[1];
              if (key === "dashboard_passcode") return;
              if (value === undefined || value === null || (typeof value === "number" && !Number.isFinite(value))) return;
              url.searchParams.set(key, typeof value === "object" ? JSON.stringify(value) : String(value));
            });
            var response = await fetch(url.toString(), {
              headers: {
                "Accept": "application/json",
                "X-Opex-Dashboard-Passcode": String(args && args.dashboard_passcode || "")
              }
            });
            var text = await response.text();
            var payload;
            try { payload = JSON.parse(text); } catch (_) { payload = null; }
            if (!response.ok) {
              var message = payload && (payload.error && (payload.error.message || payload.error) || payload.message);
              throw new Error(message || text || "The dashboard request failed.");
            }
            return payload;
          }
        }
      };
    </script>
    <script type="module">${js}</script>
  </body>
</html>`;
}

function first(query: Query, key: string) {
  const value = query[key];
  return Array.isArray(value) ? String(value[0] || "") : String(value || "");
}

function stringArray(query: Query, key: string) {
  const value = query[key];
  if (Array.isArray(value)) return value.map(String);
  if (!value) return [];
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed.map(String) : [];
  } catch {
    return String(value).split(",").map((item) => item.trim()).filter(Boolean);
  }
}

async function apiPayload(query: Query) {
  const expectedActualRaw = first(query, "expected_actual");
  return await getOpexData(
    (first(query, "action") || "collectives") as Action,
    first(query, "dashboard_passcode"),
    first(query, "collective"),
    first(query, "from"),
    first(query, "to"),
    first(query, "fiscal_year"),
    first(query, "snapshot_run_id"),
    first(query, "account_id"),
    first(query, "category_key"),
    stringArray(query, "cost_center_labels"),
    expectedActualRaw ? Number(expectedActualRaw) : Number.NaN,
  );
}

export async function preprocessor(event: {
  kind: string;
  query?: Query;
  headers?: Record<string, string | string[] | undefined>;
}) {
  if (event.kind === "http") {
    const query = { ...(event.query || {}) };
    const headers = event.headers || {};
    const passcodeHeader = headers["x-opex-dashboard-passcode"] || headers["X-Opex-Dashboard-Passcode"];
    query.dashboard_passcode = Array.isArray(passcodeHeader) ? passcodeHeader[0] : passcodeHeader || "";
    return { query };
  }
  return { query: {} };
}

export async function main(query: Query = {}) {
  if (first(query, RAW_APP_API_PARAM) === "get_opex_data") {
    return {
      windmill_content_type: "application/json; charset=utf-8",
      result: await apiPayload(query),
    };
  }

  return {
    windmill_content_type: "text/html; charset=utf-8",
    result: renderRawAppHtml(),
  };
}
